-- Backfill the core legal pages (Privacy Policy, Terms of Service,
-- Creator Quality Guidelines) so the public /legal/* pages resolve on
-- environments where the seed script was never run. ON CONFLICT DO
-- NOTHING makes this a safe one-time backfill: existing rows (e.g. edited
-- via the admin UI) are left untouched.

INSERT INTO "LegalPage" ("id", "slug", "title", "description", "effectiveDate", "sections", "createdAt", "updatedAt")
VALUES (
  gen_random_uuid(),
  $x$creator-quality-guidelines$x$,
  $x$Creator Quality Guidelines$x$,
  $x$These Creator Quality Guidelines set the standards every creator agrees to follow when producing and delivering content on GoCollab. Following them keeps your content brand-ready and helps you get booked.$x$,
  $x$June 16, 2026$x$,
  $x$[{"title":"🎥 High-Quality Video","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Record in 1080p or higher with stable, sharp footage. Avoid blurry or shaky videos.</p>","anchorId":"high-quality-video","tocLabel":"High-Quality Video","sortOrder":0},{"title":"💡 Good Lighting","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Use natural light or soft indoor lighting. Ensure both you and the product are clearly visible.</p>","anchorId":"good-lighting","tocLabel":"Good Lighting","sortOrder":1},{"title":"🎙️ Clear Audio","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Record in a quiet environment. Your voice should be crisp and free from background noise or echoes.</p>","anchorId":"clear-audio","tocLabel":"Clear Audio","sortOrder":2},{"title":"✂️ Clean Editing","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Keep edits smooth and engaging. Avoid excessive transitions, distracting effects, or heavy filters unless requested.</p>","anchorId":"clean-editing","tocLabel":"Clean Editing","sortOrder":3},{"title":"📱 Vertical Format","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Shoot in 9:16 for Reels, TikTok, and Shorts unless the campaign specifies another format.</p>","anchorId":"vertical-format","tocLabel":"Vertical Format","sortOrder":4},{"title":"📦 Showcase the Product","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Keep the product in focus, highlight its key features naturally, and avoid blocking it with your hands.</p>","anchorId":"showcase-the-product","tocLabel":"Showcase the Product","sortOrder":5},{"title":"📋 Follow the Brief","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Read the campaign instructions carefully and include all required talking points, shots, and deliverables.</p>","anchorId":"follow-the-brief","tocLabel":"Follow the Brief","sortOrder":6},{"title":"🤝 Be Professional","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Submit your content on time, communicate clearly, and deliver your best work every time.</p>","anchorId":"be-professional","tocLabel":"Be Professional","sortOrder":7}]$x$::jsonb,
  now(),
  now()
)
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "LegalPage" ("id", "slug", "title", "description", "effectiveDate", "sections", "createdAt", "updatedAt")
VALUES (
  gen_random_uuid(),
  $x$privacy-policy$x$,
  $x$Privacy Policy$x$,
  $x$This Privacy Policy explains how GoCollab collects, uses, stores, shares, and protects personal information when you access or use our platform and related services.$x$,
  $x$June 16, 2026$x$,
  $x$[{"title":"Who This Policy Applies To","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">This Privacy Policy applies to:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li><strong class=\"text-foreground\">Creators</strong> who register, create profiles, upload portfolios, submit content, or provide services through GoCollab.</li>\n  <li><strong class=\"text-foreground\">Brands, agencies, business users</strong>, and their representatives who browse creators, place orders, communicate with creators, or use GoCollab services.</li>\n  <li><strong class=\"text-foreground\">Visitors</strong> who browse our website.</li>\n  <li><strong class=\"text-foreground\">Users</strong> who contact us for support, disputes, refunds, partnerships, or general enquiries.</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">This Policy applies to personal data, meaning information that can identify an individual directly or indirectly. India&apos;s Digital Personal Data Protection Act, 2023 defines personal data broadly as data about an individual who is identifiable by or in relation to such data.</p>","anchorId":"who-this-policy-applies-to","tocLabel":"Who This Applies To","sortOrder":0},{"title":"Information We Collect","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">We may collect the following types of information:</p>\n<h3 class=\"text-lg font-semibold tracking-tight mb-3 mt-6\">A. Account Information</h3>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">When you create an account, we may collect:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Name, email address, phone number</li>\n  <li>Password or login credentials</li>\n  <li>User type (creator, brand, agency, or admin)</li>\n  <li>Business name or creator name</li>\n  <li>Profile photo or logo</li>\n  <li>Location, city, state, and country</li>\n  <li>Social media handles or portfolio links</li>\n</ul>\n<h3 class=\"text-lg font-semibold tracking-tight mb-3 mt-6\">B. Creator Profile Information</h3>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">If you register as a creator, we may collect:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Creator bio, niche/category, languages spoken</li>\n  <li>Content samples, portfolio videos or images</li>\n  <li>Pricing details and delivery timelines</li>\n  <li>Past work examples, ratings, reviews, and performance information</li>\n  <li>Payment or payout-related information</li>\n  <li>Identity or verification details, where required</li>\n</ul>\n<h3 class=\"text-lg font-semibold tracking-tight mb-3 mt-6\">C. Brand or Agency Information</h3>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">If you register as a brand or agency, we may collect:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Business name, brand website, industry or product category</li>\n  <li>Contact person details, billing details</li>\n  <li>Campaign requirements, creator preferences</li>\n  <li>Order details, briefs, scripts, references, product information, and communication records</li>\n</ul>\n<h3 class=\"text-lg font-semibold tracking-tight mb-3 mt-6\">D. Order and Collaboration Information</h3>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">When you use GoCollab to collaborate, we may collect:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Order details, accepted briefs, deliverables, uploaded content files</li>\n  <li>Messages exchanged between users</li>\n  <li>Revision requests, dispute details, refund requests</li>\n  <li>Ratings, reviews, and usage rights agreed</li>\n</ul>\n<h3 class=\"text-lg font-semibold tracking-tight mb-3 mt-6\">E. Payment Information</h3>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">We may collect or process payment-related information such as:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Billing name, billing address, payment status</li>\n  <li>Transaction ID, invoice details, GST/tax details</li>\n  <li>Payout information for creators</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">We may use third-party payment gateways or payment service providers to process payments. GoCollab does not store complete card numbers, UPI credentials, CVV numbers, or sensitive banking authentication information unless specifically required and legally permitted.</p>\n<h3 class=\"text-lg font-semibold tracking-tight mb-3 mt-6\">F. Communication Information</h3>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">When you contact us, we may collect:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Your name, email address, phone number</li>\n  <li>Support request details, feedback</li>\n  <li>Complaint or dispute information</li>\n  <li>Any attachments or evidence you submit</li>\n</ul>\n<h3 class=\"text-lg font-semibold tracking-tight mb-3 mt-6\">G. Technical and Usage Information</h3>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">When you use our website or platform, we may automatically collect:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>IP address, browser type, device type, operating system</li>\n  <li>Pages visited, time spent on pages, referring URLs</li>\n  <li>Login activity, approximate location</li>\n  <li>Cookies and tracking data, platform usage behaviour</li>\n</ul>","anchorId":"information-we-collect","tocLabel":"Information We Collect","sortOrder":1},{"title":"How We Use Your Information","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">We use your information to operate, improve, protect, and personalise GoCollab. We may use your information to:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Create and manage your account</li>\n  <li>Display creator profiles to brands and agencies</li>\n  <li>Help brands discover and book creators</li>\n  <li>Process orders, payments, refunds, and payouts</li>\n  <li>Enable communication between brands, agencies, and creators</li>\n  <li>Review submitted briefs, deliverables, revisions, disputes, and refunds</li>\n  <li>Verify creator or brand details where required</li>\n  <li>Provide customer support</li>\n  <li>Send transactional updates (order updates, payment updates, dispute updates, and platform notices)</li>\n  <li>Improve website performance and user experience</li>\n  <li>Prevent fraud, misuse, spam, fake profiles, or unauthorised activity</li>\n  <li>Enforce our Terms of Service, Creator Terms, Brand/Agency Terms, Refund Policy, and Community Guidelines</li>\n  <li>Send marketing communications, offers, product updates, and platform announcements, where permitted</li>\n  <li>Comply with legal, tax, regulatory, and accounting obligations</li>\n</ul>","anchorId":"how-we-use-your-information","tocLabel":"How We Use Your Info","sortOrder":2},{"title":"Legal Basis for Processing","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Depending on your location and applicable law, we may process your information based on:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Your consent</li>\n  <li>Performance of a contract with you</li>\n  <li>Compliance with legal obligations</li>\n  <li>Legitimate business interests</li>\n  <li>Fraud prevention and platform safety</li>\n  <li>Dispute resolution and enforcement of platform terms</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">Where consent is required, we will seek your consent before processing your personal data for that specific purpose. The DPDP framework emphasises notice, consent, and purpose-based processing of personal data.</p>","anchorId":"legal-basis-for-processing","tocLabel":"Legal Basis","sortOrder":3},{"title":"How We Share Information","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground font-medium text-foreground\">We do not sell your personal information.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">We may share your information in the following cases:</p>\n<h3 class=\"text-lg font-semibold tracking-tight mb-3 mt-6\">A. Between Brands/Agencies and Creators</h3>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">To enable collaboration, certain information may be visible to the other party, such as:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Creator profile information and brand/agency brief details</li>\n  <li>Order details, messages, submitted files</li>\n  <li>Revision requests, delivery status</li>\n  <li>Usage rights and agreed deliverables</li>\n</ul>\n<h3 class=\"text-lg font-semibold tracking-tight mb-3 mt-6\">B. With Service Providers</h3>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">We may share information with trusted third-party providers who help us operate the platform, including:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Payment gateways and hosting providers</li>\n  <li>Cloud storage providers and analytics tools</li>\n  <li>Email and SMS service providers</li>\n  <li>Customer support tools and fraud prevention tools</li>\n  <li>Legal, tax, or accounting partners</li>\n</ul>\n<h3 class=\"text-lg font-semibold tracking-tight mb-3 mt-6\">C. For Legal and Safety Reasons</h3>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">We may disclose information if required to:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Comply with applicable law or respond to lawful requests</li>\n  <li>Protect GoCollab&apos;s rights, users, or platform</li>\n  <li>Investigate fraud, abuse, disputes, or policy violations</li>\n  <li>Enforce our Terms of Service or protect against security threats</li>\n</ul>\n<h3 class=\"text-lg font-semibold tracking-tight mb-3 mt-6\">D. Business Transfers</h3>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">If GoCollab is involved in a merger, acquisition, restructuring, investment, sale of assets, or transfer of business, user information may be transferred as part of that transaction, subject to appropriate safeguards.</p>","anchorId":"how-we-share-information","tocLabel":"How We Share Info","sortOrder":4},{"title":"Creator Profiles and Public Information","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Creator profiles may be visible to brands, agencies, and other platform users. Public or semi-public creator profile information may include:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Name or creator name, profile photo, bio</li>\n  <li>Niche/category, portfolio samples, pricing</li>\n  <li>Languages, delivery timeline</li>\n  <li>Reviews, ratings, and social media links (where provided)</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">Creators should not upload personal information they do not want to be visible to potential clients or platform users.</p>","anchorId":"creator-profiles-and-public-information","tocLabel":"Creator Profiles","sortOrder":5},{"title":"Brand and Agency Briefs","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Brands and agencies may upload briefs, product information, campaign details, reference files, scripts, or other materials. These may be shared with selected creators for the purpose of completing orders.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">Brands and agencies are responsible for ensuring that they have the right to upload and share any materials, product information, trademarks, images, videos, or third-party content provided through the platform.</p>","anchorId":"brand-and-agency-briefs","tocLabel":"Brand & Agency Briefs","sortOrder":6},{"title":"Uploaded Content and Deliverables","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Creators may upload videos, images, drafts, scripts, thumbnails, voiceovers, or other deliverables. Brands may upload references, product details, campaign notes, and supporting files.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">We may process uploaded files to:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Enable order completion and support revisions</li>\n  <li>Resolve disputes and verify delivery</li>\n  <li>Enforce platform policies and maintain transaction records</li>\n  <li>Improve platform safety</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">We do not claim ownership of user content except as required to operate the platform, process orders, provide services, enforce rights, and comply with applicable policies.</p>","anchorId":"uploaded-content-and-deliverables","tocLabel":"Uploaded Content","sortOrder":7},{"title":"Platform Promotional Usage Rights","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">By uploading, submitting, or delivering content through LetsCollab, including videos, images, testimonials, campaign deliverables, portfolio samples, or other creative assets, you grant LetsCollab and Messold Technologies a non-exclusive, worldwide, royalty-free license to use, display, reproduce, publish, showcase, and promote such content on the LetsCollab platform, including but not limited to the homepage, creator profiles, case studies, marketing materials, social media channels, presentations, advertisements, emails, and other areas of the platform for the purpose of promoting LetsCollab and its services.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">This license does not transfer ownership of the content to LetsCollab. The creator or rightful owner retains all ownership rights in the content. LetsCollab will make reasonable efforts to attribute content to the relevant creator, brand, or agency where appropriate.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">If a brand, agency, or creator believes certain content should not be used for promotional purposes due to confidentiality obligations or other legitimate concerns, they may submit a written request to LetsCollab for review.</p>","anchorId":"platform-promotional-usage-rights","tocLabel":"Promotional Usage Rights","sortOrder":8},{"title":"Dispute and Refund Review Data","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">If you request a dispute review, refund, cancellation, or payment release review, we may collect and review:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Order details, accepted brief, communication records</li>\n  <li>Submitted files, delivery proof, revision history</li>\n  <li>Payment status, reason for dispute, requested resolution</li>\n  <li>Supporting evidence from both parties</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">GoCollab may use this information to make a reasonable marketplace decision, including approval, revision request, refund, credit, rejection of refund, cancellation of refund, or release of payment.</p>","anchorId":"dispute-and-refund-review-data","tocLabel":"Dispute & Refund Data","sortOrder":9},{"title":"Cookies and Tracking Technologies","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">We may use cookies, pixels, tags, and similar technologies to:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Keep users logged in and remember preferences</li>\n  <li>Improve website performance and understand user behaviour</li>\n  <li>Analyse traffic and improve marketing campaigns</li>\n  <li>Prevent fraud and misuse</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">You can control cookies through your browser settings. However, disabling cookies may affect certain features of the platform.</p>","anchorId":"cookies-and-tracking","tocLabel":"Cookies & Tracking","sortOrder":10},{"title":"Marketing Communications","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">We may send you emails, SMS, WhatsApp messages, push notifications, or other communications related to:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Account updates, order updates, platform updates</li>\n  <li>Offers and promotions</li>\n  <li>Creator opportunities and brand/agency opportunities</li>\n  <li>Product announcements and educational content</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">You may opt out of promotional communications at any time by using the unsubscribe option or contacting us. However, we may still send transactional or service-related communications.</p>","anchorId":"marketing-communications","tocLabel":"Marketing","sortOrder":11},{"title":"Data Security","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">We take reasonable technical and organisational measures to protect personal information against unauthorised access, loss, misuse, disclosure, alteration, or destruction.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">These measures may include:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Access controls and password protection</li>\n  <li>Encryption where appropriate</li>\n  <li>Secure hosting and internal access restrictions</li>\n  <li>Monitoring for suspicious activity</li>\n  <li>Regular review of security practices</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">However, no online platform can guarantee 100% security. Users are responsible for keeping their login credentials confidential.</p>","anchorId":"data-security","tocLabel":"Data Security","sortOrder":12},{"title":"Data Retention","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">We retain personal information only for as long as necessary for the purposes described in this Privacy Policy, including:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Providing platform services and maintaining user accounts</li>\n  <li>Completing orders, processing payments and payouts</li>\n  <li>Handling disputes and refunds</li>\n  <li>Complying with tax, accounting, and legal obligations</li>\n  <li>Preventing fraud and misuse</li>\n  <li>Enforcing our Terms of Service</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">After the retention period ends, we may delete, anonymise, or securely archive the information, unless longer retention is required by law.</p>","anchorId":"data-retention","tocLabel":"Data Retention","sortOrder":13},{"title":"Your Rights","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Depending on applicable law, you may have the right to:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Access your personal information</li>\n  <li>Correct or update inaccurate information</li>\n  <li>Request deletion of your information</li>\n  <li>Withdraw consent, where processing is based on consent</li>\n  <li>Object to certain types of processing</li>\n  <li>Request information about how your data is used</li>\n  <li>Request grievance redressal</li>\n  <li>Nominate another person to exercise your rights in certain circumstances, where applicable</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">To exercise your rights, contact us at:</p>\n<div class=\"rounded-lg border border-border bg-muted/30 p-4 text-sm leading-relaxed text-muted-foreground\">\n  <p><span class=\"font-medium text-foreground\">Email:</span> <a href=\"mailto:support@gocollab.io\" class=\"text-primary underline underline-offset-2 hover:text-primary/80\">support@gocollab.io</a></p>\n  <p class=\"mt-1\"><span class=\"font-medium text-foreground\">Subject Line:</span> Privacy Request – GoCollab</p>\n</div>\n<p class=\"mb-4 leading-relaxed text-muted-foreground mt-4\">We may verify your identity before processing your request.</p>","anchorId":"your-rights","tocLabel":"Your Rights","sortOrder":14},{"title":"Account Deletion","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">You may request deletion of your account by contacting us at <a href=\"mailto:support@gocollab.io\" class=\"text-primary underline underline-offset-2 hover:text-primary/80\">support@gocollab.io</a>.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">Please note:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Some information may be retained for legal, tax, fraud prevention, dispute resolution, or contractual reasons.</li>\n  <li>Deleted creator profiles may no longer be visible to brands.</li>\n  <li>Deleting your account may not automatically delete completed order records, invoices, payment records, dispute records, or legally required records.</li>\n  <li>If you have active orders, disputes, unpaid balances, or pending payouts, deletion may be delayed until those matters are resolved.</li>\n</ul>","anchorId":"account-deletion","tocLabel":"Account Deletion","sortOrder":15},{"title":"Children's Privacy","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">GoCollab is not intended for users below the age of 18 years, unless permitted by applicable law and with appropriate consent from a parent or legal guardian.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">We do not knowingly collect personal information from children. If we become aware that a child has provided personal information without proper consent, we may delete such information and restrict account access.</p>","anchorId":"childrens-privacy","tocLabel":"Children's Privacy","sortOrder":16},{"title":"International Data Transfers","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Your information may be stored or processed in countries other than your country of residence, depending on our hosting, payment, analytics, and service providers.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">Where required by law, we will take appropriate steps to protect transferred personal information through contractual, technical, or organisational safeguards.</p>","anchorId":"international-data-transfers","tocLabel":"International Transfers","sortOrder":17},{"title":"Third-Party Links","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">GoCollab may contain links to third-party websites, social media profiles, payment gateways, portfolio links, or external tools.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">We are not responsible for the privacy practices, content, or security of third-party websites. Users should review the privacy policies of those third-party services before sharing information with them.</p>","anchorId":"third-party-links","tocLabel":"Third-Party Links","sortOrder":18},{"title":"Third-Party Integrations","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">GoCollab may integrate with third-party tools such as payment providers, analytics platforms, communication tools, video hosting services, or social platforms.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">When you use such integrations, your information may also be processed according to the third party&apos;s own terms and privacy policy.</p>","anchorId":"third-party-integrations","tocLabel":"Third-Party Integrations","sortOrder":19},{"title":"User Responsibilities","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">You agree to:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Provide accurate and updated information</li>\n  <li>Not upload another person&apos;s personal data without authority</li>\n  <li>Not share confidential information publicly</li>\n  <li>Keep your login details secure</li>\n  <li>Use the platform in compliance with applicable laws</li>\n  <li>Respect privacy, intellectual property, and communication boundaries of other users</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">Brands, agencies, and creators are responsible for ensuring that the materials they upload or share do not violate privacy rights, publicity rights, intellectual property rights, or applicable laws.</p>","anchorId":"user-responsibilities","tocLabel":"User Responsibilities","sortOrder":20},{"title":"Changes to This Privacy Policy","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">We may update this Privacy Policy from time to time. If we make material changes, we may notify users through:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Email</li>\n  <li>Platform notification</li>\n  <li>Website notice</li>\n  <li>Updated &quot;Last Updated&quot; date</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">Your continued use of GoCollab after the updated Privacy Policy becomes effective means you accept the revised Policy.</p>","anchorId":"changes-to-this-privacy-policy","tocLabel":"Changes to Policy","sortOrder":21},{"title":"Grievance Officer / Contact Us","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">For privacy questions, complaints, account deletion requests, data access requests, or grievance redressal, contact:</p>\n<div class=\"rounded-lg border border-border bg-muted/30 p-5 text-sm leading-relaxed text-muted-foreground\">\n  <p><span class=\"font-medium text-foreground\">Company:</span> Messold Technologies</p>\n  <p class=\"mt-1\"><span class=\"font-medium text-foreground\">Platform:</span> GoCollab</p>\n  <p class=\"mt-1\"><span class=\"font-medium text-foreground\">Website:</span> <a href=\"https://www.messold.com\" class=\"text-primary underline underline-offset-2 hover:text-primary/80\" target=\"_blank\" rel=\"noopener noreferrer\">www.messold.com</a></p>\n  <p class=\"mt-1\"><span class=\"font-medium text-foreground\">Email:</span> <a href=\"mailto:support@gocollab.io\" class=\"text-primary underline underline-offset-2 hover:text-primary/80\">support@gocollab.io</a></p>\n</div>\n<p class=\"mb-4 leading-relaxed text-muted-foreground mt-4\">The DPDP Act gives individuals the right to have readily available means of grievance redressal from the data fiduciary.</p>","anchorId":"grievance-officer-contact","tocLabel":"Contact / Grievance","sortOrder":22}]$x$::jsonb,
  now(),
  now()
)
ON CONFLICT ("slug") DO NOTHING;

INSERT INTO "LegalPage" ("id", "slug", "title", "description", "effectiveDate", "sections", "createdAt", "updatedAt")
VALUES (
  gen_random_uuid(),
  $x$terms-of-service$x$,
  $x$Terms of Service$x$,
  $x$These Terms of Service govern your access to and use of the GoCollab platform. Please read them carefully before using our services.$x$,
  $x$June 16, 2026$x$,
  $x$[{"title":"Introduction and Acceptance","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">These Terms of Service (&quot;Terms&quot;) govern access to and use of the GoCollab website, marketplace, dashboards, communication tools, payment flows, and related services (collectively, the &quot;Platform&quot;).</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">The Platform is operated by Messold Technologies, having its registered office at J-6, Block J, Reserve Bank Enclave, Paschim Vihar, Delhi, 110063 (&quot;GoCollab&quot;, &quot;we&quot;, &quot;us&quot;, or &quot;our&quot;).</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">By creating an account, browsing the Platform, placing an order, accepting a project, submitting deliverables, or otherwise using the Platform, you agree to be bound by these Terms, our Privacy Policy, Refund and Cancellation Policy, Creator Guidelines, Community Guidelines, and any project-specific order terms accepted through the Platform.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">If you are using the Platform on behalf of a company, agency, brand, client, or other entity, you confirm that you have authority to bind that entity to these Terms.</p>","anchorId":"introduction-and-acceptance","tocLabel":"Introduction & Acceptance","sortOrder":0},{"title":"Key Definitions","content":"<div class=\"overflow-x-auto rounded-lg border border-border\">\n  <table class=\"w-full text-left text-sm\">\n    <thead><tr class=\"border-b border-border bg-muted/50\"><th class=\"whitespace-nowrap px-4 py-3 font-semibold text-foreground\">Term</th><th class=\"px-4 py-3 font-semibold text-foreground\">Meaning</th></tr></thead>\n    <tbody class=\"divide-y divide-border text-muted-foreground\">\n      <tr><td class=\"whitespace-nowrap px-4 py-3 font-medium text-foreground\">Brand / Agency</td><td class=\"px-4 py-3\">A business, agency, advertiser, marketer, ecommerce store, or individual that uses the Platform to find, book, brief, or pay creators for content.</td></tr>\n      <tr><td class=\"whitespace-nowrap px-4 py-3 font-medium text-foreground\">Creator</td><td class=\"px-4 py-3\">A user who lists a creator profile, accepts project briefs, produces UGC, and submits deliverables through the Platform.</td></tr>\n      <tr><td class=\"whitespace-nowrap px-4 py-3 font-medium text-foreground\">UGC</td><td class=\"px-4 py-3\">User-generated content or creator-generated content, including videos, photos, scripts, voiceovers, raw footage, edits, hooks, testimonials, product demos, unboxings, and related creative assets.</td></tr>\n      <tr><td class=\"whitespace-nowrap px-4 py-3 font-medium text-foreground\">Project / Order</td><td class=\"px-4 py-3\">A collaboration initiated through the Platform between a Brand/Agency and Creator, including the agreed brief, deliverables, pricing, timeline, revisions, and usage rights.</td></tr>\n      <tr><td class=\"whitespace-nowrap px-4 py-3 font-medium text-foreground\">Deliverables</td><td class=\"px-4 py-3\">The content files, drafts, final edits, source files, captions, scripts, or other materials that a Creator agrees to provide.</td></tr>\n      <tr><td class=\"whitespace-nowrap px-4 py-3 font-medium text-foreground\">Platform Fee</td><td class=\"px-4 py-3\">Any commission, service fee, processing fee, subscription fee, or other amount charged by GoCollab for facilitating the marketplace.</td></tr>\n      <tr><td class=\"whitespace-nowrap px-4 py-3 font-medium text-foreground\">Usage Rights</td><td class=\"px-4 py-3\">The license or permission granted to use the Deliverables for specified purposes, channels, territories, durations, and formats.</td></tr>\n    </tbody>\n  </table>\n</div>","anchorId":"key-definitions","tocLabel":"Key Definitions","sortOrder":1},{"title":"Eligibility, Account, and Agency Authority","content":"<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>You must be legally capable of entering into contracts and must provide accurate, current, and complete account information.</li>\n  <li>If you are an agency or representative, you confirm that you are authorised to act for your client and to approve budgets, briefs, content use, and payments.</li>\n  <li>You are responsible for all activity under your account, including actions by employees, contractors, clients, or team members you invite.</li>\n  <li>GoCollab may refuse, suspend, or terminate accounts that provide misleading information, violate these Terms, or create risk for creators, brands, users, or the Platform.</li>\n</ul>","anchorId":"eligibility-account-and-agency-authority","tocLabel":"Eligibility & Account","sortOrder":2},{"title":"Marketplace Role of GoCollab","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">GoCollab provides a marketplace and workflow layer to help Brands/Agencies discover creators, review creator profiles, issue project briefs, make payments, communicate, receive deliverables, and manage disputes. Unless expressly stated in writing, GoCollab is not the employer, agent, partner, representative, or manager of any Creator.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">Creators are independent service providers. GoCollab does not guarantee specific creative performance, advertising results, sales, ROAS, engagement, virality, brand lift, or conversion outcomes from UGC.</p>","anchorId":"marketplace-role","tocLabel":"Marketplace Role","sortOrder":3},{"title":"Brand Briefs, Orders, and Responsibilities","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Before placing an order, you are responsible for providing a clear and complete brief. A good brief should include:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Product or service details and key claims</li>\n  <li>Content format, length, aspect ratio, language, style, tone, and references</li>\n  <li>Mandatory talking points, prohibited claims, and compliance guidelines</li>\n  <li>Number of deliverables, revisions, raw files if required, deadlines, and submission format</li>\n  <li>Usage rights required, including paid ads, organic social, whitelisting, website use, edits, and duration</li>\n  <li>Product shipping, creator access, coupon codes, scripts, and any required brand assets</li>\n</ul>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">You confirm that all information, products, claims, references, music, assets, instructions, and materials you provide are accurate, lawful, and do not infringe any third-party rights.</p>","anchorId":"brand-briefs-orders-and-responsibilities","tocLabel":"Briefs, Orders & Responsibilities","sortOrder":4},{"title":"Creator Selection and Verification","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Creator profiles may include portfolios, niches, pricing, sample content, ratings, location, language, delivery timelines, and other creator-supplied information. While GoCollab may use verification, moderation, or quality review processes, you are responsible for evaluating whether a creator is suitable for your brand, product, audience, and campaign requirements.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">GoCollab may remove or restrict profiles that appear misleading, unsafe, inactive, or inconsistent with Platform standards, but we do not guarantee that every creator profile or sample is error-free, continuously updated, or suitable for every use case.</p>","anchorId":"creator-selection-and-verification","tocLabel":"Creator Selection","sortOrder":5},{"title":"Payments, Platform Fees, and Taxes","content":"<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>You agree to pay all amounts shown at checkout or in the accepted order, including creator fees, Platform Fees, payment processing charges, taxes, shipping reimbursements, usage-rights upgrades, rush fees, and any other agreed charges.</li>\n  <li>Unless stated otherwise, payment may be collected upfront and held or processed according to the Platform payment workflow. GoCollab may release payment to the Creator after the project is marked delivered, approved, auto-approved, or otherwise eligible for release under the applicable order terms.</li>\n  <li>You are responsible for any applicable taxes, withholding obligations, invoices, and compliance requirements arising from your purchase or use of the Deliverables, except to the extent GoCollab is legally required to collect or remit a specific tax.</li>\n</ul>","anchorId":"payments-platform-fees-and-taxes","tocLabel":"Payments & Fees","sortOrder":6},{"title":"Refunds, Cancellations, and Disputes","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Refunds and cancellations are handled under the applicable Refund and Cancellation Policy and the specific facts of the order. In general, a Brand/Agency may be eligible for support, revision, replacement, credit, partial refund, or full refund where a Creator fails to deliver the agreed content, materially misses the accepted brief, submits unusable files, or abandons the order.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">Refunds are not guaranteed merely because the content does not achieve expected ad results, engagement, conversions, sales, or subjective preference if the Creator delivered according to the accepted brief.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">If you request a dispute review, you must provide the order details, accepted brief, communication records, submitted files, reason for dispute, and requested resolution within the timeline shown on the Platform. GoCollab may review evidence and make a reasonable marketplace decision, including approval, revision request, refund, credit, or release of payment. Messold Technologies reserves the right to deny or cancel any refund request at its sole discretion if the submitted evidence is incomplete, insufficient, inconsistent with the accepted brief, or does not reasonably support the dispute claim.</p>","anchorId":"refunds-cancellations-and-disputes","tocLabel":"Refunds & Disputes","sortOrder":7},{"title":"Review Rounds and Acceptance","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">The number of included revisions will be stated in the order or creator offer. Revisions must relate to the accepted brief and should not introduce materially new requirements, new scripts, new products, new locations, new actors, new formats, or new usage rights unless the Creator agrees and additional fees are paid where applicable.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">Deliverables may be treated as accepted if you approve them, download or use them, fail to request revisions within the stated review period, or otherwise indicate acceptance through the Platform.</p>","anchorId":"review-rounds-and-acceptance","tocLabel":"Review Rounds","sortOrder":8},{"title":"Usage Rights and Intellectual Property","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Unless otherwise stated in the order, Creators retain ownership of their underlying creative work, likeness, raw footage, templates, methods, and pre-existing materials, and Brands/Agencies receive only the Usage Rights expressly purchased or agreed through the Platform.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">You must not use Deliverables outside the agreed scope. Examples of additional rights that may require a separate license or fee include paid advertising, whitelisting/spark ads/creator account boosting, perpetual use, exclusivity, category lockout, TV/OTT, marketplace listings, app store ads, outdoor advertising, use after the license term, or major editing that changes the Creator context or endorsement.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">You are responsible for ensuring that all claims in the final content are legally substantiated, compliant with advertising standards, and suitable for your product category.</p>","anchorId":"usage-rights-and-intellectual-property","tocLabel":"Usage Rights & IP","sortOrder":9},{"title":"Brand Content, Product Claims, and Regulated Categories","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">You must not request content that is false, misleading, illegal, unsafe, deceptive, discriminatory, infringing, defamatory, sexually exploitative, hateful, or otherwise prohibited by Platform policies. You must not ask Creators to make claims that they cannot honestly make or that require professional, medical, financial, legal, or regulatory substantiation unless you provide lawful and accurate instructions.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">Regulated or sensitive categories, including but not limited to healthcare, supplements, financial services, gambling, alcohol, tobacco/nicotine, adult products, political content, and products aimed at children, may require additional review or may be restricted or prohibited.</p>","anchorId":"brand-content-product-claims-and-regulated-categories","tocLabel":"Brand Content & Claims","sortOrder":10},{"title":"Communication and Off-Platform Dealings","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">To maintain payment protection, dispute support, order records, and user safety, project communication, approvals, revisions, and payment should take place through the Platform unless GoCollab expressly allows otherwise.</p>\n<p class=\"mb-4 leading-relaxed text-muted-foreground\">You must not use the Platform to discover a Creator and then intentionally avoid Platform fees by moving the same or substantially similar transaction off-platform, unless permitted by GoCollab in writing.</p>","anchorId":"communication-and-off-platform-dealings","tocLabel":"Communication","sortOrder":11},{"title":"Confidentiality","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">You may share confidential product, launch, pricing, campaign, or brand information with a Creator only when necessary for the project. You may request confidentiality obligations in the project brief or separate NDA. GoCollab is not responsible for confidential information you disclose outside the Platform or without appropriate protections.</p>","anchorId":"confidentiality","tocLabel":"Confidentiality","sortOrder":12},{"title":"Platform Use Restrictions","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">You must not:</p>\n<ul class=\"mb-4 list-disc space-y-2 pl-6 text-muted-foreground leading-relaxed\">\n  <li>Interfere with Platform security, scraping controls, account systems, or payment systems.</li>\n  <li>Misrepresent your identity, agency authority, product category, campaign purpose, or required usage rights.</li>\n  <li>Harass, pressure, threaten, or discriminate against creators.</li>\n  <li>Request fake testimonials, undisclosed paid endorsements, unlawful reviews, or misleading before/after claims.</li>\n  <li>Upload malware, infringing assets, unlawful content, or personal data that you are not permitted to share.</li>\n</ul>","anchorId":"platform-use-restrictions","tocLabel":"Use Restrictions","sortOrder":13},{"title":"Suspension and Termination","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">GoCollab may suspend or terminate your account, cancel orders, restrict features, remove content, withhold or reverse payment releases where legally permitted, or take other reasonable action if you breach these Terms, create risk, engage in fraud, misuse creator content, or violate Platform policies.</p>","anchorId":"suspension-and-termination","tocLabel":"Suspension & Termination","sortOrder":14},{"title":"Disclaimers","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">The Platform is provided on an &quot;as is&quot; and &quot;as available&quot; basis. GoCollab does not warrant uninterrupted availability, error-free operation, specific creator performance, advertising results, sales, engagement, or that any Deliverable will meet subjective expectations beyond the accepted order scope.</p>","anchorId":"disclaimers","tocLabel":"Disclaimers","sortOrder":15},{"title":"Limitation of Liability","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">To the maximum extent permitted by law, GoCollab will not be liable for indirect, incidental, special, consequential, exemplary, or punitive damages, including lost profits, lost revenue, lost data, loss of goodwill, or advertising underperformance. GoCollab&apos;s total liability arising out of or related to an order will not exceed the amount of Platform Fees received by GoCollab for that specific order, unless applicable law requires otherwise.</p>","anchorId":"limitation-of-liability","tocLabel":"Limitation of Liability","sortOrder":16},{"title":"Indemnity","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">You agree to indemnify and hold harmless GoCollab, its affiliates, officers, employees, contractors, and partners from claims, losses, liabilities, damages, costs, and expenses arising from your products, claims, instructions, assets, misuse of Deliverables, breach of Usage Rights, breach of these Terms, violation of law, or infringement of third-party rights.</p>","anchorId":"indemnity","tocLabel":"Indemnity","sortOrder":17},{"title":"Privacy and Data","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">Your use of the Platform is subject to our Privacy Policy. You must process creator personal data only for the relevant project and in accordance with applicable privacy laws. You must not add creators to marketing lists, share their details with unrelated parties, or use their data for purposes outside the project without permission.</p>","anchorId":"privacy-and-data","tocLabel":"Privacy & Data","sortOrder":18},{"title":"Governing Law and Dispute Resolution","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">These Terms are governed by the laws of India, unless another governing law is required by mandatory consumer or platform law. Subject to applicable law, courts located in Delhi, India will have exclusive jurisdiction over disputes that cannot be resolved through Platform support or good-faith negotiation.</p>","anchorId":"governing-law-and-dispute-resolution","tocLabel":"Governing Law","sortOrder":19},{"title":"Changes to These Terms","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">GoCollab may update these Terms from time to time. Updated Terms will be posted on the Platform with a new effective date. Continued use of the Platform after changes become effective means you accept the updated Terms.</p>","anchorId":"changes-to-these-terms","tocLabel":"Changes to Terms","sortOrder":20},{"title":"Contact","content":"<p class=\"mb-4 leading-relaxed text-muted-foreground\">For legal, policy, refund, or support questions, contact Messold Technologies.</p>\n<div class=\"rounded-lg border border-border bg-muted/30 p-5 text-sm leading-relaxed text-muted-foreground\">\n  <p><span class=\"font-medium text-foreground\">Company:</span> Messold Technologies</p>\n  <p class=\"mt-1\"><span class=\"font-medium text-foreground\">Platform:</span> GoCollab</p>\n  <p class=\"mt-1\"><span class=\"font-medium text-foreground\">Website:</span> <a href=\"https://www.messold.com\" class=\"text-primary underline underline-offset-2 hover:text-primary/80\" target=\"_blank\" rel=\"noopener noreferrer\">www.messold.com</a></p>\n  <p class=\"mt-1\"><span class=\"font-medium text-foreground\">Email:</span> <a href=\"mailto:support@gocollab.io\" class=\"text-primary underline underline-offset-2 hover:text-primary/80\">support@gocollab.io</a></p>\n</div>","anchorId":"contact","tocLabel":"Contact","sortOrder":21}]$x$::jsonb,
  now(),
  now()
)
ON CONFLICT ("slug") DO NOTHING;

